def semver_sort(versions):
    def make_key(v):
        # strip build metadata
        core_pre = v.split('+', 1)[0]
        if '-' in core_pre:
            core, pre = core_pre.split('-', 1)
        else:
            core, pre = core_pre, None
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is None:
            pre_flag = 1
            pre_key = ()
        else:
            pre_flag = 0
            ids = pre.split('.')
            pre_key = tuple(
                (0, int(i)) if i.isdigit() else (1, i)
                for i in ids
            )
        return (major, minor, patch, pre_flag, pre_key)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (make_key(pair[1]), pair[0]))
    return [v for _, v in indexed]

